// Renders the React Email templates (scripts/emails) into supabase/functions/_shared/email-templates.generated.js,
// the file the `campaigns` Edge Function sends from. The functions run on Deno and never import React.
//
//   npm run build:emails            writes the generated file
//   npm run preview:emails          also writes one HTML file per email to scripts/emails/preview/ (open in a browser)
//
// Re-run it after any change in scripts/emails and commit the generated file.

import { build } from "esbuild";
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, resolve } from "node:path";
import { fillTemplate, sampleValues } from "../supabase/functions/_shared/email-render.js";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const tmp = resolve(root, "scripts/emails/.build");
rmSync(tmp, { recursive: true, force: true });
mkdirSync(tmp, { recursive: true });

await build({
  entryPoints: [resolve(root, "scripts/emails/render.jsx")],
  outfile: resolve(tmp, "render.mjs"),
  bundle: true,
  platform: "node",
  format: "esm",
  jsx: "automatic",
  packages: "external",
  logLevel: "warning",
});

const { renderAll } = await import(pathToFileURL(resolve(tmp, "render.mjs")).href);
const templates = await renderAll();
rmSync(tmp, { recursive: true, force: true });

const header = "// GENERATED by scripts/build-emails.mjs from scripts/emails. Do not edit; run `npm run build:emails`.\n";
writeFileSync(
  resolve(root, "supabase/functions/_shared/email-templates.generated.js"),
  `${header}export const TEMPLATES = ${JSON.stringify(templates, null, 1)};\n`,
);
console.log(`templates: ${Object.keys(templates).length} campaigns x 2 languages -> supabase/functions/_shared/email-templates.generated.js`);

if (process.argv.includes("--preview")) {
  const dir = resolve(root, "scripts/emails/preview");
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
  const index = [];
  for (const [type, langs] of Object.entries(templates)) {
    for (const [lang, t] of Object.entries(langs)) {
      const values = sampleValues(lang);
      const name = `${type}.${lang}`;
      writeFileSync(resolve(dir, `${name}.html`), fillTemplate(t.html, values, { html: true }));
      writeFileSync(resolve(dir, `${name}.txt`), fillTemplate(t.text, values));
      index.push(`<li><a href="${name}.html">${name}</a> (<a href="${name}.txt">text</a>) &mdash; ${Object.values(t.subjects).join(" / ")}</li>`);
    }
  }
  writeFileSync(resolve(dir, "index.html"), `<!doctype html><meta charset="utf-8"><title>Email previews</title><body style="font-family:sans-serif"><h1>Email previews</h1><ul>${index.join("")}</ul>`);
  console.log(`preview: ${index.length} emails -> scripts/emails/preview/index.html`);
}
